INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (70157, 'author', '林俊雄');
INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (70157, 'culture_entry_ref_id', 157);
